import json
from datetime import date
from decimal import Decimal
from pathlib import Path
from typing import List
from expense_tracker.data.transaction_loader import TransactionLoader
from expense_tracker.domain.models import Transaction
from expense_tracker.domain.exceptions import DataLoadError, ValidationError
from expense_tracker.reports.report_factory import ReportFactory

class JSONTransactionLoader(TransactionLoader):
    """Loads transactions from a JSON array of objects."""
    def load(self, source: str) -> List[Transaction]:
        path = Path(source)
        if not path.exists():
            raise DataLoadError(f"File not found: {source}")
        try:
            records = json.loads(path.read_text(encoding='utf-8'))
        except json.JSONDecodeError as e:
            raise DataLoadError(f"Invalid JSON in {source}: {e}") from e
        if not isinstance(records, list):
            raise ValidationError("Top-level JSON value must be an array")
        transactions = []
        for i, record in enumerate(records, start=1):
            try:
                transactions.append(Transaction(
                    date=date.fromisoformat(record['date']),
                    amount=Decimal(str(record['amount'])),
                    category=record['category'],
                    description=record['description'],
                ))
            except KeyError as e:
                raise ValidationError(f"Missing field {e}", row_number=i) from e
            except (ValueError, ArithmeticError) as e:
                raise ValidationError(str(e), row_number=i) from e
        return transactions
    def validate_source(self, source: str) -> bool:
        try:
            p = Path(source)
            return p.exists() and p.is_file()
        except Exception:
            return False

l = JSONTransactionLoader()
txns = l.load('/tmp/ug/exp.json')
print("loaded:", len(txns), "|", txns[0])
print(ReportFactory.create_report('category').process_transactions(txns))
for f in ['missing.json','notlist.json','broken.json']:
    try: l.load(f'/tmp/ug/{f}')
    except (DataLoadError, ValidationError) as e: print(f"{f} -> {type(e).__name__}: {e}")
print("validate_source:", l.validate_source('/tmp/ug/exp.json'), l.validate_source('/tmp/ug/nope.json'))
try: l.load('/tmp/ug/nope.json')
except DataLoadError as e: print("missing file ->", e)
