files = ['README.md','docs/user_guide.md','docs/api_reference.md',
         'docs/architecture.md','docs/contributing.md','docs/troubleshooting.md']

def slug(h):
    # github-slugger: lowercase, drop non-alphanumeric/space/hyphen/underscore,
    # spaces -> hyphens, NO collapsing, NO trimming of hyphens
    h = h.strip().lower()
    h = re.sub(r'[^a-z0-9 _-]', '', h)
    return h.replace(' ', '-')

anchors = {}
for f in files:
    txt = pathlib.Path(f).read_text()
    anchors[f] = {slug(h) for h in re.findall(r'^#{1,6}\s+(.*)$', txt, re.M)}

bad = []
total = 0
for f in files:
    base = pathlib.Path(f).parent
    txt = pathlib.Path(f).read_text()
    for label, target in re.findall(r'\[([^\]]+)\]\(([^)]+)\)', txt):
        if target.startswith('http'): continue
        total += 1
        path, _, frag = target.partition('#')
        if path == '':
            tgt = f
        else:
            p = (base / path).resolve()
            if not p.exists():
                bad.append(f'{f}: MISSING FILE -> {target}'); continue
            tgt = str(p.relative_to(pathlib.Path('.').resolve()))
        if frag and frag not in anchors.get(tgt, set()):
            bad.append(f'{f}: BAD ANCHOR "{label}" -> {target}')

